<?php

declare(strict_types=1);

namespace App\Services\Rag;

/**
 * Issues and validates the credential that binds a visitor to a conversation.
 *
 * The conversation identifier is generated by the server on the first turn and
 * travels to the client together with an HMAC signature over `APP_KEY`. A
 * request without a valid credential opens a new conversation instead of
 * trusting a client-supplied identifier (R6, D7).
 */
class ConversationToken
{
    private const SEPARATOR = '.';

    public function issue(string $sessionId): string
    {
        return $sessionId.self::SEPARATOR.$this->sign($sessionId);
    }

    public function conversationId(string $token): ?string
    {
        $token = trim($token);

        if ($token === '') {
            return null;
        }

        $position = strrpos($token, self::SEPARATOR);

        if ($position === false) {
            return null;
        }

        $sessionId = substr($token, 0, $position);
        $signature = substr($token, $position + 1);

        if ($sessionId === '' || $signature === '' || mb_strlen($sessionId) > 100) {
            return null;
        }

        if (! hash_equals($this->sign($sessionId), $signature)) {
            return null;
        }

        return $sessionId;
    }

    private function sign(string $sessionId): string
    {
        return hash_hmac('sha256', $sessionId, (string) config('app.key'));
    }
}
